/**
 * #723 R-2 — THE ROTARY RELIEF CAM, pinned on a solid of revolution.
 *
 * The fixture is a cone (radius 4 → 9 mm over 30 mm) on a ⌀20 rod. The program is generated by
 * `generateRotaryReliefIR`, posted, parsed, timed and swept on the ROTARY column engine — the
 * same engines a real job goes through — and the swept radius is compared with the cone's closed
 * form. A second test pins the roughing's own rule: no rough move reaches more than the allowance
 * below the goal.
 */
import { describe, expect, it } from 'vitest';
import { generateRotaryReliefIR, sampleGoalRadialField } from '@/engine/cnc/cam/rotaryRelief';
import { postZ1, type PostContext } from '@/engine/cnc/post/z1';
import { buildTimeline, parseGcode, stubSetup, Z1, type Setup } from '@/engine/cnc';
import { verifyProgram } from '@/engine/cnc/verify';
import { flatEndMill, type Tool } from '@/engine/cnc/tool';
import { columnSweep } from '@/workers/geometry/columnEngine';
import type { RapidEstimate } from '@/engine/cnc/cam/ir';
import type { SurfaceFeeds } from '@/engine/cnc/cam/surface3d';
import type { EngraveTargetObject } from '@/types/engraveJob';

type V = [number, number, number];
type Tri = [V, V, V];

function stl(tris: Tri[]): string {
  const buf = new ArrayBuffer(84 + tris.length * 50);
  const dv = new DataView(buf);
  dv.setUint32(80, tris.length, true);
  let off = 84;
  for (const t of tris) {
    off += 12;
    for (const v of t) {
      dv.setFloat32(off, v[0], true);
      dv.setFloat32(off + 4, v[1], true);
      dv.setFloat32(off + 8, v[2], true);
      off += 12;
    }
    off += 2;
  }
  return Buffer.from(new Uint8Array(buf)).toString('base64');
}

const R = 10;
const LENGTH = 30;
const CX = 30;
const TAU = Math.PI * 2;
const R_AT = (x: number): number => 4 + ((x - (CX - LENGTH / 2)) / LENGTH) * 5;

/** The cone's side surface, local X centred on 0. */
function coneTris(seg = 180): Tri[] {
  const tris: Tri[] = [];
  const at = (x: number, a: number): V => {
    const r = R_AT(CX + x);
    return [x, r * Math.sin(a), r * Math.cos(a)];
  };
  for (let i = 0; i < seg; i++) {
    const a0 = (i / seg) * TAU;
    const a1 = ((i + 1) / seg) * TAU;
    tris.push([at(-LENGTH / 2, a0), at(LENGTH / 2, a0), at(LENGTH / 2, a1)], [
      at(-LENGTH / 2, a0),
      at(LENGTH / 2, a1),
      at(-LENGTH / 2, a1),
    ]);
  }
  return tris;
}

function goal(): EngraveTargetObject {
  return {
    id: 'cone',
    name: 'cone.stl',
    format: 'stl',
    sha256: 'c'.repeat(64),
    data: stl(coneTris()),
    size: { x: LENGTH, y: 18, z: 18 },
    position: { x: CX, y: 0, z: 0 },
    rotation: 0,
    enabled: true,
    role: 'goal',
  };
}

const BALL2: Tool = flatEndMill(2, { shape: 'ball', name: '2 mm ball', fluteLength: 12, shoulderLength: 20 });
const RAPID: RapidEstimate = { xyMmPerMin: 1200, zMmPerMin: 600, accelMmPerS2: 150, source: 'test' };
const FEEDS: SurfaceFeeds = { feed: 600, plungeFeed: 200, stepDown: 1.5, roughStepOver: 1.2, finishStepOver: 0.4 };
const ALLOWANCE = 0.3;

const ctx = (): PostContext => ({
  jobName: 'rotary relief cam',
  stock: { length: 100, width: 2 * R, thickness: 2 * R },
  materialName: 'pla',
  zDatum: 'rotary-axis',
  origin: 'topFrontLeft',
  camVersion: '1.0.0',
  toolKey: 'fixture',
});
const STOCK = { kind: 'cylinder' as const, diameter: 2 * R, length: 100 };
const HOLD = { kind: 'rotary-chuck' as const, jawDiameter: 40, stickout: 60 };
const setup = (): Setup => stubSetup(STOCK, HOLD, { startingTool: 1 }, Z1);

function build() {
  const field = sampleGoalRadialField(goal(), R, { pitchMm: 0.5 });
  const ir = generateRotaryReliefIR({
    field,
    tool: BALL2,
    toolNumber: 1,
    spindleRpm: 12000,
    air: true,
    feeds: FEEDS,
    rapid: RAPID,
    stockToLeaveMm: ALLOWANCE,
  });
  return { field, ir };
}

describe('#723 R-2 — the relief program posts, parses and sweeps to the cone', () => {
  it('generates roughing and finishing in the rotary frame', () => {
    const { ir } = build();
    expect(ir.ir.frame).toBe('rotary');
    expect(ir.ir.operations).toHaveLength(2);
    expect(ir.roughing.moves.length).toBeGreaterThan(0);
    expect(ir.finishing.moves.length).toBeGreaterThan(0);
    expect(ir.roughingLayers).toBeGreaterThan(0);
    expect(ir.radius).toBe(R);
  });

  it('the finishing passes hold one A angle and the roughing turns A', () => {
    const { ir } = build();
    const fin = ir.finishing.moves.filter((m) => m.kind === 'feed');
    // Every finishing feed move has an A word (the wrap's map rows are A angles).
    expect(fin.every((m) => (m as { a?: number }).a !== undefined)).toBe(true);
    const rough = ir.roughing.moves.filter((m) => m.kind === 'feed');
    const as = rough.map((m) => (m as { a?: number }).a ?? 0);
    expect(Math.max(...as) - Math.min(...as)).toBeGreaterThan(300);
  });

  it('posts as a wrapped program that parses and verifies clean', () => {
    const { ir } = build();
    const posted = postZ1(ir.ir, ctx(), Z1);
    if (!posted.ok) throw new Error(posted.errors.slice(0, 3).join('; '));
    const timeline = buildTimeline(parseGcode(posted.text), setup());
    expect(timeline.summary.rotaryClass).toBe('wrapped');
    expect(timeline.diagnostics.filter((d) => d.severity === 'error')).toEqual([]);
    const verified = verifyProgram(posted.text, {
      setup: setup(),
      machine: Z1,
      tool: BALL2,
      depthLimit: () => 0,
      minRapidZ: 1,
      rotary: { radius: R, stickout: 60, tailstock: false },
    });
    expect(verified.findings.filter((f) => f.severity === 'error').map((f) => `${f.line} ${f.message}`)).toEqual([]);
  });

  it('the swept radius follows the cone within the finish’s scallop, never gouging it', () => {
    const { ir } = build();
    const posted = postZ1(ir.ir, ctx(), Z1);
    if (!posted.ok) throw new Error(posted.errors.slice(0, 3).join('; '));
    const timeline = buildTimeline(parseGcode(posted.text), setup());
    const out = columnSweep(timeline, BALL2, setup(), { resolution: { dx: 0.25, dThetaDeg: 0.5 } });
    if (!out.ok) throw new Error(JSON.stringify(out.diagnostics));
    const g = out.grid;
    const at = (x: number, thetaDeg: number): number => {
      const i = Math.round((x - g.u0) / g.du);
      const j = ((Math.round(thetaDeg / g.dv) % g.nv) + g.nv) % g.nv;
      return g.h[j * g.nu + i] as number;
    };
    let gouge = 0;
    let excess = 0;
    let cut = false;
    for (let x = CX - 10; x <= CX + 10; x += 0.5) {
      for (let t = 0; t < 360; t += 15) {
        const got = at(x, t);
        const truth = R_AT(x);
        gouge = Math.max(gouge, truth - got); // material cut INSIDE the goal (undersize)
        excess = Math.max(excess, got - truth); // material left standing above it
        if (got < R - 1) cut = true;
      }
    }
    expect(cut).toBe(true);
    // The ball's scallop at a 0.4 mm step-over is 0.02 mm; the grid (0.25 × 0.5°) adds a sliver.
    expect(gouge).toBeLessThan(0.12);
    expect(excess).toBeLessThan(0.12);
  });

  it('no roughing move reaches more than the allowance below the goal', () => {
    const { field, ir } = build();
    const feed = ir.roughing.moves.filter((m) => m.kind === 'feed');
    let worst = Infinity;
    for (const m of feed) {
      const i = Math.round((m.x - field.x0) / field.pitch);
      const j = ((Math.round(m.y / field.pitch) % field.ny) + field.ny) % field.ny;
      const idx = j * field.nx + i;
      if (idx < 0 || idx >= field.z.length) continue;
      const floor = (field.covered[idx] === 1 ? (field.z[idx] as number) : 0) + ALLOWANCE;
      // A rough move's Z (map height) sits at or above the goal + allowance everywhere it cuts.
      worst = Math.min(worst, m.z - floor);
      expect(m.z).toBeGreaterThanOrEqual(field.minRadius - field.radius + ALLOWANCE - 1e-6);
    }
    expect(worst).toBeGreaterThan(-1e-6);
  });

  it('a surface that reaches the axis is refused with the design’s words', () => {
    const { field } = build();
    expect(() =>
      generateRotaryReliefIR({
        field: { ...field, minRadius: 0 },
        tool: BALL2,
        toolNumber: 1,
        spindleRpm: 12000,
        air: true,
        feeds: FEEDS,
        rapid: RAPID,
      }),
    ).toThrow(/cuts through the centre/);
  });
});
